function replaceVariables(template, variables) {
    var result = template;
    for (var key in variables) {
        if (variables.hasOwnProperty(key)) {
            var placeholder = '{{' + key + '}}';
            result = result.split(placeholder).join(variables[key]);
        }
    }
    return result;
}

function timestampToReadableDate(timestamp) {
    var offset = 6 * 60 * 60 * 1000;
    var date = new Date(timestamp-offset);

    var year = date.getFullYear();
    var month = ('0' + (date.getMonth() + 1)).slice(-2); // Los meses van de 0 a 11
    var day = ('0' + date.getDate()).slice(-2);

    var hours = ('0' + date.getHours()).slice(-2);
    var minutes = ('0' + date.getMinutes()).slice(-2);
    var seconds = ('0' + date.getSeconds()).slice(-2);

    return year + "-" + month + "-" + day + " " + hours + ":" + minutes + ":" + seconds;
}

