var dispositivo = JSON.parse(metadata.dispositivo);
var deviceKey = (dispositivo.mac !== undefined) ? dispositivo.mac : dispositivo.token;
var canalesConfig = metadata.notificacionesConfiguracion ? JSON.parse(metadata.notificacionesConfiguracion) : {};
var mapaDispositivos = metadata.notificacionesDispositivos ? JSON.parse(metadata.notificacionesDispositivos) : {};

var sendEmail = false;
var sendTelegram = false;
var correos = '';

if(!deviceKey || !mapaDispositivos[deviceKey]){
    metadata.sendEmail = sendEmail;
    metadata.sendTelegram = sendTelegram;

    return { msg: msg, metadata: metadata, msgType: msgType };
}

var canalesDestino = mapaDispositivos[deviceKey].split(",");
var correosUnificados = [];

canalesDestino.forEach(function (canal) {
    canal = canal.trim();

    if (canal === "T") {
        sendTelegram = true;
    } else if (!isNaN(canal)) {
        var index = parseInt(canal);
        if (canalesConfig.email && Array.isArray(canalesConfig.email.correos) && canalesConfig.email.correos[index]) {
            correosUnificados.push(canalesConfig.email.correos[index]);
        }
    }
});

if(correosUnificados.length > 0){
